import {leafKitchenCopy as T,leafKitchenCards} from './leaf-kitchen-content.mjs';
import {changeLeafKitchen,leafKitchenModel,leafKitchenNarration} from './leaf-kitchen-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,value='',extra='')=>`<button type="button" class="secondary" data-lk-action="${action}" data-lk-value="${esc(value)}" ${extra}>${esc(label)}</button>`;
function icon(card){let shape;switch(card.icon){case 'drop':shape='<path d="M24 5C20 14 10 23 10 32a14 14 0 0 0 28 0C38 23 28 14 24 5Z"/>';break;case 'sun':shape='<circle cx="24" cy="24" r="10"/><path d="M24 2v7m0 30v7M2 24h7m30 0h7M8 8l5 5m22 22 5 5M8 40l5-5m22-22 5-5"/>';break;case 'dissolved':shape='<path d="M9 10v29h30V10M9 24q8-6 15 0t15 0"/><circle cx="18" cy="30" r="2"/><circle cx="30" cy="34" r="2"/>';break;case 'sugar':shape='<path d="M11 30q0-17 13-17t13 17M9 34h30"/><path d="M18 25h12m-6-6v12"/>';break;default:shape='<path d="M8 22q6-7 12 0t12 0t9 0M5 31q6-7 12 0t12 0t12 0" fill="none"/>';}
return `<svg class="lk-icon" viewBox="0 0 48 48" aria-hidden="true" focusable="false">${shape}</svg>`;}
function tag(card,work,interactive){return interactive?`<button type="button" class="secondary lk-tag" data-lk-action="select" data-lk-value="${card.id}" aria-pressed="${work.selected===card.id}"${work.selected===card.id?' aria-disabled="true"':''}>${icon(card)}<span>${esc(card.label)}</span></button>`:`<span class="lk-tag">${icon(card)}<span>${esc(card.label)}</span></span>`;}
function roles(roles,work,interactive){if(!interactive)return `<dl class="lk-readonly-roles">${roles.map(r=>`<div data-lk-role="${r.id}"><dt>${esc(r.label)}</dt><dd>${esc(r.cards.length?r.cards.map(c=>c.label).join(' · '):T.emptyRole)}</dd></div>`).join('')}</dl>`;return `<div class="lk-roles">${roles.map(r=>`<section class="lk-role" data-lk-role="${r.id}">${interactive?button('place',r.label,r.id,`${!work.selected?'disabled':work.placements[work.selected]===r.id?'aria-disabled="true"':''}`):`<h4>${esc(r.label)}</h4>`}<div class="lk-role-cards">${r.cards.map(c=>tag(c,work,interactive)).join('')||`<p>${esc(T.emptyRole)}</p>`}</div></section>`).join('')}</div>`;}
// Scientific paths appear only in the explicit reference and teaching pictures.
function picture(kind){const night=kind==='night',all=kind==='reference';const path=(id,d,cls='')=>`<path data-lk-path="${id}" class="lk-path ${cls}" d="${d}"/>`;
let paths='';if(all||kind==='materials')paths+=path('carbon-dioxide','M24 94H130l-10-7m10 7-10 7')+path('water','M160 246V147l-7 10m7-10 7 10','lk-water')+path('minerals','M142 244Q198 223 172 176l-1 12m1-12 10 6','lk-minerals');if(all||kind==='energy')paths+=path('light','M280 34 190 93l12-1m-12 1 5-11','lk-energy');if(all||kind==='gas')paths+=path('oxygen','M191 124h100l-10-7m10 7-10 7','lk-gas');if(all||kind==='food'||night)paths+=`<g data-lk-path="${night?'stored-food':'food'}" class="lk-food"><ellipse cx="160" cy="115" rx="17" ry="11"/><path d="M151 115h18m-9-6v12"/>${night?'<circle cx="124" cy="211" r="7"/><circle cx="148" cy="220" r="7"/>':''}</g>`;
const key=[];const addKey=(card,arrow,style)=>key.push(`<li><span aria-hidden="true" class="lk-key-mark ${style}"></span><span>${esc(leafKitchenCards[card].label)} · ${esc(T[arrow])}</span></li>`);if(all||kind==='materials'){addKey(0,'materialArrow','lk-key-material');addKey(1,'materialArrow','lk-key-water');addKey(3,'mineralsArrow','lk-key-minerals');}if(all||kind==='energy')addKey(2,'energyArrow','lk-key-energy');if(all||kind==='food')addKey(4,'foodArrow','lk-key-food');if(all||kind==='gas')addKey(5,'gasArrow','lk-key-gas');const legend=night?'':`<figcaption><p>${esc(T.leafLabel)} · ${esc(T.rootsLabel)}</p><ul class="lk-diagram-key">${key.join('')}</ul></figcaption>`;
return `<figure class="lk-figure">${legend}<svg class="lk-picture${night?' lk-night':''}" data-lk-picture="${kind}" viewBox="0 0 320 280" aria-hidden="true" focusable="false"><path class="lk-stem" d="M160 115v98"/><path class="lk-leaf" d="M160 145C80 135 101 53 190 59c27 33 19 71-30 86Z"/><path class="lk-root" d="M160 211v35m0-24-27 30m27-20 27 20m-27-12-10 27"/>${night?'<path class="lk-moon" d="M275 26a23 23 0 1 0 23 32 25 25 0 0 1-23-32Z"/>':''}${paths}</svg></figure>`;}
function sourceReference(m,work){const r=m.reference;return `<section class="lk-reference" data-lk-reference><h3 id="lk-reference-title" tabindex="-1">${esc(T.reference)}</h3>${roles(r.roles,work,false)}<p>${esc(r.wordEquation)}</p><p>${esc(r.wordEquationNote)}</p><p>${esc(r.notice)}</p><p>${esc(T.diagramCaption)}</p>${picture('reference')}</section>`;}
export function leafKitchenPage(work){const m=leafKitchenModel(work);let body='';if(m.page==='build')body=`<h2 id="lk-page-title" tabindex="-1">${esc(T.build)}</h2><p>${esc(T.buildInstruction)}</p><p data-lk-selected>${esc(T.selected)}: ${esc(m.selected?.label||T.noneSelected)}</p><div class="ll-actions">${button('remove',T.remove,'',!m.selected?'disabled':work.placements[work.selected]===null?'aria-disabled="true"':'')}${button('new-arrangement',T.newArrangement,'',!m.selected&&!work.reference&&Object.values(work.placements).every(v=>v===null)?'disabled':'')}</div><h3>${esc(T.unplaced)}</h3><div class="lk-rack">${m.unplaced.map(c=>tag(c,work,true)).join('')}</div><h3>${esc(T.yourIdea)}</h3><p>${esc(T.yourNotice)}</p>${roles(m.roles,work,true)}`;
if(m.page==='compare')body=`<h2 id="lk-page-title" tabindex="-1">${esc(T.compare)}</h2><p>${esc(T.compareInstruction)}</p><div class="lk-comparison"><section><h3>${esc(T.yourIdea)}</h3><p>${esc(T.yourNotice)}</p>${roles(m.roles,work,false)}<h4>${esc(T.unplaced)}</h4><ul class="lk-word-list">${m.unplaced.map(c=>`<li>${esc(c.label)}</li>`).join('')}</ul></section><section><div class="ll-actions">${button('show-reference',T.showReference,'',m.reference?'disabled':'')}${button('page',T.edit,'build')}</div>${m.reference?sourceReference(m,work):`<p data-lk-reference-hidden>${esc(T.referenceHidden)}</p>`}</section></div>`;
if(m.page==='learn'){const t=m.teaching;body=`<h2 id="lk-page-title" tabindex="-1">${esc(T.learn)}</h2><p>${esc(T.learnInstruction)}</p><h3 id="lk-step-title" tabindex="-1">${esc(t.title)}</h3><div class="ll-actions">${button('step',T.previousStep,work.step-1,work.step===0?'disabled':'')}${button('step',T.nextStep,work.step+1,work.step===4?'disabled':'')}</div><p>${esc(t.text)}</p><p>${esc(t.caption)}</p>${picture(t.picture)}`;}
if(m.page==='questions'){const q=m.invitation;body=`<h2 id="lk-page-title" tabindex="-1">${esc(T.questions)}</h2><p>${esc(T.questionsInstruction)}</p><h3 id="lk-question" tabindex="-1">${esc(q.prompt)}</h3><div class="lk-choices">${q.choices.map(c=>button('answer',c.label,c.id,`aria-pressed="${q.choice?.id===c.id}" ${q.choice?.id===c.id?'disabled':''}`)).join('')}</div>${m.feedback?`<p id="lk-feedback" role="status" tabindex="-1"><strong>${esc(T[m.feedback.outcome])}</strong> ${esc(m.feedback.text)}</p>${button('question',T.tryAgain,work.invitation)}`:''}${button('question',T.nextQuestion,(work.invitation+1)%4)}`;}
return `<div class="ll-page lk-page" data-lk-root><header><div class="ll-actions">${button('back',T.back)}<button type="button" class="secondary" data-lk-hear data-speak="">${esc(T.hear)}</button></div><h1 id="lk-title" tabindex="-1">${esc(T.title)}</h1><p>${esc(T.story)}</p></header><nav class="ll-actions" aria-label="${esc(T.title)}">${['build','compare','learn','questions'].map(p=>button('page',T[p],p,`${p===work.page?'disabled':''} aria-current="${p===work.page?'page':'false'}"`)).join('')}</nav>${body}<footer><p class="ll-notice">${esc(T.notice)}</p><p>${esc(T.visitNote)}</p><p>${esc(T.parentLeaveWarning)}</p><details data-lk-grownup><summary>${esc(T.grownupTitle)}</summary><p>${esc(T.grownup)}</p></details><details data-lk-leave><summary>${esc(T.leaveTitle)}</summary><p id="lk-leave-warning">${esc(T.leaveWarning)}</p><section aria-describedby="lk-leave-warning"><h3>${esc(T.returnTitle)}</h3><p>${esc(T.returnText)}</p><a href="#living/plants" aria-describedby="lk-leave-warning">${esc(T.returnLink)}</a></section><section aria-describedby="lk-leave-warning"><h3>${esc(T.nextTitle)}</h3><p>${esc(T.nextText)}</p><a href="#living/bodies" aria-describedby="lk-leave-warning">${esc(T.nextLink)}</a></section></details></footer></div>`;}
export function bindLeafKitchen(work,ctx){const root=document.querySelector('[data-lk-root]');if(!root)return;root.querySelectorAll('button,a,summary').forEach(n=>n.addEventListener('click',e=>{if(!ctx.live(n)||n.disabled||n.getAttribute('aria-disabled')==='true'){e.preventDefault();e.stopImmediatePropagation();return;}if(n.matches('summary'))return;ctx.stopSpeech?.();ctx.stopSound?.();if(n.matches('a'))return;if(n.matches('[data-lk-hear]')){n.dataset.speak=leafKitchenNarration(work);return;}e.preventDefault();const action=n.dataset.lkAction;if(action==='back'){ctx.back();return;}let value=n.dataset.lkValue;if(action==='step'||action==='question')value=Number(value);const next=changeLeafKitchen(work,action,value);if(!next)return;ctx.change(next);ctx.render();const focus=action==='new-arrangement'?'#lk-title':action==='page'?'#lk-page-title':action==='show-reference'?'#lk-reference-title':action==='step'?'#lk-step-title':action==='question'?'#lk-question':action==='answer'?'#lk-feedback':`[data-lk-action="${action}"][data-lk-value="${CSS.escape(n.dataset.lkValue)}"]`;ctx.focus?.(focus);},{capture:true}));}
